// Loop over input items
for (const item of $input.all()) {
  // Extract the "content" field from the JSON
  const content = item.json.choices[0].message.content;

  // Remove surrounding quotes and split by commas
  const contentWithoutQuotes = content.replace(/^"|"$/g, ''); // Убираем кавычки в начале и конце
  const contentArray = contentWithoutQuotes.split('","'); // Разбиваем по запятым и кавычкам

  // Add the extracted data to the JSON as a new field
  item.json.contentArray = contentArray;
}

// Return the modified items
return $input.all();

