// Получаем входные данные
const inputData = $input.all();

// Обрабатываем каждый элемент входных данных
const result = inputData.map(item => {
  const text = item.json.text;

  // Регулярные выражения для извлечения данных
  const companyNameRegex = /"company_name":\s*"([^"]+)"/;
  const descriptionRegex = /"description":\s*"([^"]+)"/;
  const automationOpportunitiesRegex = /"automation_opportunities":\s*"([^"]+)"/;
  const analysisRegex = /"analysis":\s*"([\s\S]*?)"(?=\s*(?:\n|,|}|$))/;

  // Извлекаем название компании
  const companyNameMatch = text.match(companyNameRegex);
  const companyName = companyNameMatch ? companyNameMatch[1] : null;

  // Извлекаем описание
  const descriptionMatch = text.match(descriptionRegex);
  const description = descriptionMatch ? descriptionMatch[1] : null;

  // Извлекаем возможности автоматизации
  const automationOpportunitiesMatch = text.match(automationOpportunitiesRegex);
  const automationOpportunities = automationOpportunitiesMatch
    ? automationOpportunitiesMatch[1] // Оставляем как строку
    : null;

  // Извлекаем разбор (анализ, потребности, предложения)
  const analysisMatch = text.match(analysisRegex);
  const analysis = analysisMatch ? analysisMatch[1].trim() : null;

  // Возвращаем новый объект с извлечёнными данными
  return {
    json: {
      companyName: companyName,
      description: description,
      automationOpportunities: automationOpportunities, // Возвращаем как строку
      analysis: analysis
    }
  };
});

// Возвращаем результат
return result;

