// Получаем очищенный текст из предыдущего шага
const cleanText = $json.cleanText;

// Регулярное выражение для поиска email
const emailRegex = /[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.(?!png|jpg|gif|jpeg)[a-zA-Z]{2,}/g;

// Регулярное выражение для поиска телефонов (Россия)
const phoneRegex = /(?:\+7|8|7|\(\d{3}\))[\s\-()]*\d{3}[\s\-()]*\d{2}[\s\-()]*\d{2}|(?:\+7|8|7)?[\s\-()]*\d{3}[\s\-()]*\d{3}[\s\-()]*\d{2}[\s\-()]*\d{2}/g;

// Извлекаем email
const emails = cleanText.match(emailRegex) || [];

// Извлекаем телефоны
const phones = cleanText.match(phoneRegex) || [];

// Возвращаем результат
return {
  json: {
    emails: emails,
    phones: phones
  }
};

// Получаем HTML-код страницы
const data = $json.data;

// Очищаем HTML от стилей и скриптов
const cleanHTML = data.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>|<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '');

// Извлекаем содержимое тега <body>
const bodyMatch = cleanHTML.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
const bodyContent = bodyMatch ? bodyMatch[1] : '';

// Получаем чистый текст из <body>
const cleanText = bodyContent.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();

// Возвращаем результат
return {
  json: {
    cleanText: cleanText
  }
